import{_ as t,o,c as a,a0 as i}from"./chunks/framework.CShDTZbC.js";const p=JSON.parse('{"title":"Phase 3A: Agent Loop Extraction","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/phase-3-agent-loop.md","filePath":"internals/hackathon-archive/phase-3-agent-loop.md"}'),n={name:"internals/hackathon-archive/phase-3-agent-loop.md"};function r(s,e,l,c,h,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="phase-3a-agent-loop-extraction" tabindex="-1">Phase 3A: Agent Loop Extraction <a class="header-anchor" href="#phase-3a-agent-loop-extraction" aria-label="Permalink to &quot;Phase 3A: Agent Loop Extraction&quot;">​</a></h1><p>Based on the empirical success of the Local Dev Environment Troubleshooter in Phase 2D.5, we have extracted the minimal viable autonomous loop required to reproduce the behavior.</p><h2 id="_1-initial-state" tabindex="-1">1. Initial State <a class="header-anchor" href="#_1-initial-state" aria-label="Permalink to &quot;1. Initial State&quot;">​</a></h2><ul><li><strong>Input:</strong> The agent receives a broken workspace directory and a &quot;Start Command&quot; (e.g., <code>docker build -t app . &amp;&amp; docker run app</code>).</li><li><strong>System Prompt:</strong> Instructions on its role as a Local Dev Troubleshooter, emphasizing observation before modification, and strict adherence to resolving the root cause without rewriting the entire application.</li></ul><h2 id="_2-required-tools-minimal-set" tabindex="-1">2. Required Tools (Minimal Set) <a class="header-anchor" href="#_2-required-tools-minimal-set" aria-label="Permalink to &quot;2. Required Tools (Minimal Set)&quot;">​</a></h2><p>To replicate Antigravity&#39;s success, the agent only needs three core capabilities:</p><ol><li><strong><code>execute_command(command: string)</code>:</strong> Runs a bash command in the sandbox and returns stdout/stderr and exit code.</li><li><strong><code>read_file(filepath: string)</code>:</strong> Returns the contents of a file.</li><li><strong><code>patch_file(filepath: string, target: string, replacement: string)</code>:</strong> Modifies a specific block of text in a file.</li></ol><h2 id="_3-the-autonomous-loop-react" tabindex="-1">3. The Autonomous Loop (ReAct) <a class="header-anchor" href="#_3-the-autonomous-loop-react" aria-label="Permalink to &quot;3. The Autonomous Loop (ReAct)&quot;">​</a></h2><p>The system executes a classic Reasoning + Acting (ReAct) loop:</p><ol><li><strong>OBSERVE:</strong> The system deterministically runs the Start Command and feeds the <code>stderr</code>/<code>stdout</code> crash log to the agent.</li><li><strong>DIAGNOSE (Thought):</strong> The LLM analyzes the stack trace and forms a hypothesis. If the error is ambiguous (e.g., <code>MODULE_NOT_FOUND</code>), the agent issues a <code>read_file</code> or <code>execute_command(ls -la)</code> tool call to gather more context.</li><li><strong>ACT:</strong> The agent issues a modifying tool call (e.g., <code>execute_command(npm install)</code> or <code>patch_file(Dockerfile)</code>).</li><li><strong>SYSTEM EXECUTION:</strong> The runner executes the tool in the sandbox and appends the result to the conversation.</li><li><strong>VERIFY:</strong> The agent runs the Start Command again to see if the issue is resolved.</li><li><strong>UPDATE HYPOTHESIS:</strong> If the command still fails, the agent observes the <em>new</em> error (cascading failure) and repeats from Step 2.</li></ol><h2 id="_4-loop-termination" tabindex="-1">4. Loop Termination <a class="header-anchor" href="#_4-loop-termination" aria-label="Permalink to &quot;4. Loop Termination&quot;">​</a></h2><p>The agent loop stops when:</p><ul><li>The agent explicitly calls a <code>finish(success: boolean, summary: string)</code> tool, OR</li><li>The independent deterministic verifier intercepts a successful Start Command execution (Exit Code 0) and forcefully terminates the loop, OR</li><li>The absolute iteration limit is reached (e.g., <code>MAX_ITERATIONS = 5</code>).</li></ul><h2 id="_5-safeties-resource-exhaustion-prevention" tabindex="-1">5. Safeties &amp; Resource Exhaustion Prevention <a class="header-anchor" href="#_5-safeties-resource-exhaustion-prevention" aria-label="Permalink to &quot;5. Safeties &amp; Resource Exhaustion Prevention&quot;">​</a></h2><ul><li><strong>Context Truncation:</strong> Command outputs over 2000 characters are truncated before being fed back to the LLM to prevent context window overflow.</li><li><strong>Deterministic Limits:</strong> The loop is strictly capped at 5-10 iterations by the Python/Node controller, completely outside the LLM&#39;s control.</li><li><strong>Duplicate Action Rejection:</strong> The controller tracks tool calls. If the agent submits the exact same <code>patch_file</code> or <code>execute_command</code> twice in a row, the controller intercepts it, injects a system warning to the LLM, and forces it to rethink.</li></ul>',15)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
